To generate a private DSA key and export it as a PEM-formatted string in JavaScript, you can use the `crypto` module which provides cryptographic functionality. Here's how to implement it:

```javascript
const crypto = require('crypto');

/**
 * Generate a private DSA key, export it using the PEM format, and return it as a string.
 *
 * @returns {string} The DSA private key in PEM format.
 */
function create_private_key_dsa() {
    // Create a new DSA key pair
    const key = crypto.generateKeyPairSync('dsa', {
        modulusLength: 2048,
        exponent: '2',
        publicKeyEncoding: {
            type: 'spki',
            format: 'pem'
        },
        privateKeyEncoding: {
            type: 'pkcs8',
            format: 'pem',
            cipher: 'aes-256-cbc',
            passphrase: ''
        }
    });

    // Return the private key in PEM format
    return key.privateKey;
}
```

